#!/usr/bin/env python3
"""Generate the native journal guide from Bastion Library's public expedition export."""
import argparse
import json
from pathlib import Path


def lua(text: str) -> str:
    return json.dumps(text, ensure_ascii=False)


def render(catalog: dict) -> str:
    if catalog["version"] != 1 or catalog["id"] != "mistmoore-eclipse":
        raise ValueError("Expected the Mistmoore Eclipse version 1 catalog")
    entry = catalog["entry"]
    lines = [
        "-- Generated by tools/update_journal_catalog.py from the Bastion Library export.",
        "return {",
        f"  entryName = {lua(entry['name'])},",
        f"  entryLocation = {lua(entry['location'])},",
    ]
    for key in ("normal", "bloodbound", "vigil"):
        mode = catalog["modes"][key]
        unlock = mode["unlock"]
        guide = mode["guide"]
        title = guide[0]["title"] if key == "vigil" else catalog["title"]
        mode_key = "hard" if key == "bloodbound" else key
        keywords = ", ".join(lua(keyword) for keyword in mode["requestKeywords"])
        lines.extend((
            f"  {mode_key} = {{",
            f"    name = {lua(mode['label'])},",
            f"    title = {lua(title)},",
            f"    minRoster = {mode['minRoster']}, maxRoster = {mode['maxRoster']},",
            f"    minLevel = {mode['minLevel'] or 'nil'}, tunedFor = {lua(mode['tunedFor'])},",
            f"    instanceHours = {mode['instanceSeconds'] // 3600}, replayHours = {mode['replaySeconds'] // 3600},",
            f"    requestKeywords = {{{keywords}}}, enterKeyword = {lua(mode['enterKeyword'])},",
            f"    unlockKind = {lua(unlock['kind'])},",
            "    relics = {",
        ))
        for item in unlock["items"]:
            lines.append(f"      {{id = {item['id']}, name = {lua(item['name'])}}},")
        lines.extend(("    },", "    encounters = {"))
        for encounter in guide:
            lines.append(f"      {{{lua(encounter['title'])}, {lua(encounter['summary'])}, {lua(encounter['slug'])}}},")
        lines.extend(("    },", "  },"))
    lines.extend(("}", ""))
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("export", type=Path, help="JSON from /library/api/v1/expeditions/mistmoore-eclipse")
    args = parser.parse_args()
    content = render(json.loads(args.export.read_text(encoding="utf-8")))
    root = Path(__file__).resolve().parents[1]
    for pack in ("modern", "gamepad"):
        (root / "ui" / pack / "lib" / "expedition_journal_catalog.lua").write_text(
            content, encoding="utf-8", newline="\n"
        )


if __name__ == "__main__":
    main()
